-- STAFF-ROSTER-1 (2026-11-04, charter pillar reach; cost pillar): a UI/UX auditor and a project manager join the virtual staff, and papers.qnfo.org gets a product manager.
-- Audit that led here (qnfo-audit, 2026-11-04 16:20Z): product personas existed but had 0 actions and 0 plus_ledger rows ever shipped; no role checked what a person sees.
-- The check itself is deterministic (qnfo-fleet-dashboard 1.84.0 uxAudit, no model call, hourly, table site_ux_checks). This workflow is SQL only; the single model call is
-- one cheap agent request per product per day, only under a score of 85, capped at 2 in flight, routed through the existing roadmap path (roadmap-<program>-ux-<product>-<day>)
-- so the code loop, canary and auto-revert apply. It adds no step to management-personas-c.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE fleet_crons SET enabled = 0 WHERE name = 'staff-roster-hourly'; UPDATE fleet_tasks SET enabled = 0 WHERE id = 'staff-roster'; UPDATE management_personas SET status = 'retired' WHERE persona_key IN ('ux:auditor','project-manager:fleet'); UPDATE product_registry SET state = 'retired' WHERE product = 'papers';

CREATE TABLE IF NOT EXISTS site_ux_checks (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), product TEXT NOT NULL, host TEXT, status INTEGER, ms INTEGER, bytes INTEGER, score INTEGER, findings TEXT);
CREATE INDEX IF NOT EXISTS idx_site_ux_checks_product ON site_ux_checks (product, id);

INSERT OR IGNORE INTO product_registry (product, host, worker, program_code, what_for, plus_cadence_h, state)
VALUES ('papers', 'papers.qnfo.org', 'qnfo-gateway', 'QNFO.RSCH', 'the public reading room for the fleet''s research papers: find, read, cite and report an error in a paper', 24, 'active');

INSERT OR REPLACE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('staff-roster', 'STAFF-ROSTER-1: UI/UX auditor and project manager (SQL only)', 'workflow', '{"steps": [{"type": "sql", "name": "personas", "db": "AUDIT", "sql": "INSERT OR IGNORE INTO management_personas (persona_key, level, scope, charter, decision_authority, sla_min, path_a, status, updated_at) VALUES (''ux:auditor'',''function'',''ux'',''Look at every product site the way a person meets it (layout, accessibility, typography, speed, broken pages) and keep raising the lowest score.'',''requests one fix per product per day through the roadmap path when the latest score is under 85; capped at 2 in flight'',60,''fleet_tasks staff-roster'',''active'',datetime(''now'')),(''project-manager:fleet'',''project'',''projects'',''Keep every active project moving: name idle and stale projects every hour so the program managers and roadmap loops act on them.'',''reports idle and stale projects; the roadmap and lifecycle loops own the changes'',120,''fleet_tasks staff-roster'',''active'',datetime(''now''))"}, {"type": "sql", "name": "ux-request", "db": "AUDIT", "sql": "INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''program-manager:'' || r.program_code, ''run'', ''You are the UI and UX reviewer of '' || r.product || '' ('' || r.host || ''), run in the QNFO fleet (repository QNFO/qnfo-workers). A deterministic check of the live page just scored it '' || c.score || '' of 100 (status '' || c.status || '', '' || c.ms || '' ms, '' || c.bytes || '' bytes). Findings (k = rule, d = points lost, n = count): '' || c.findings || ''. The code is '' || r.worker || ''/worker.js. Plus it: keep what works and make the smallest change that fixes the most points lost, for the person using a phone or a screen reader. Never read or quote personal data. Reply in exactly this form, each on its own line:'' || char(10) || ''TITLE: <under 80 characters>'' || char(10) || ''WHY: <who notices it and the finding it clears, under 60 words>'' || char(10) || ''code-task: repo=qnfo-workers path='' || r.worker || ''/worker.js'' || char(10) || ''code-anchor: <verbatim text that occurs exactly once in that file, next to the edit>'' || char(10) || ''EDIT: <the exact change, under 100 words>'', ''roadmap-'' || r.program_code || ''-ux-'' || r.product || ''-'' || strftime(''%Y%m%d'',''now''), ''low'' FROM product_registry r JOIN site_ux_checks c ON c.id = (SELECT MAX(x.id) FROM site_ux_checks x WHERE x.product = r.product) WHERE r.state = ''active'' AND r.worker IS NOT NULL AND c.score < 85 AND c.status BETWEEN 200 AND 399 AND c.ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-3 hours'') AND NOT EXISTS (SELECT 1 FROM json_each(''[\"qnfo-fleet-control\",\"qnfo-ops\",\"qnfo-deploy-guard\",\"qnfo-containers-pilot\",\"qnfo-autonomy-scorer\",\"qnfo-observability\",\"qnfo-code-orchestrator\",\"qnfo-code-agent\",\"personal-api\",\"personal-companion\"]'') d WHERE d.value = r.worker) AND NOT EXISTS (SELECT 1 FROM cf_agent_requests q WHERE q.instance = ''roadmap-'' || r.program_code || ''-ux-'' || r.product || ''-'' || strftime(''%Y%m%d'',''now'')) AND NOT EXISTS (SELECT 1 FROM roadmap_proposals p WHERE p.request_instance LIKE ''roadmap-%-ux-'' || r.product || ''-%'' AND p.status IN (''proposed'',''filed'',''building'')) AND (SELECT COUNT(*) FROM cf_agent_requests q WHERE q.instance LIKE ''roadmap-%-ux-%'' AND q.status IN (''queued'',''running'')) < 2 ORDER BY c.score LIMIT 1"}, {"type": "sql", "name": "ux-log", "db": "AUDIT", "sql": "INSERT INTO persona_actions (persona_key, kind, from_value, to_value, evidence) SELECT ''ux:auditor'',''ux-request'', q.instance, ''queued'', ''site check under 85, one agent request filed through the roadmap path'' FROM cf_agent_requests q WHERE q.instance LIKE ''roadmap-%-ux-%'' AND q.created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-2 hours'') AND NOT EXISTS (SELECT 1 FROM persona_actions a WHERE a.persona_key = ''ux:auditor'' AND a.from_value = q.instance)"}, {"type": "sql", "name": "ux-brief", "db": "AUDIT", "sql": "INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) SELECT strftime(''%Y-%m-%dT%H:00:00Z'',''now''), ''ux:auditor'',''function'',''ux'', CASE WHEN COUNT(*) = 0 THEN ''no-data'' WHEN MIN(score) < 70 THEN ''poor'' WHEN MIN(score) < 85 THEN ''watch'' ELSE ''good'' END, ''one fix request per product per day under 85'', COALESCE(''Latest site scores: '' || group_concat(product || '' '' || score || '' ('' || ms || '' ms)'', '', '') || ''.'', ''No site check yet.'') FROM (SELECT c.product, c.score, c.ms FROM site_ux_checks c WHERE c.id IN (SELECT MAX(id) FROM site_ux_checks GROUP BY product) ORDER BY c.score)"}, {"type": "sql", "name": "pm-brief", "db": "AUDIT", "sql": "INSERT OR REPLACE INTO persona_briefs (tick, persona_key, level, scope, verdict, decision, summary) SELECT strftime(''%Y-%m-%dT%H:00:00Z'',''now''), ''project-manager:fleet'',''project'',''projects'', CASE WHEN idle > 40 THEN ''idle-heavy'' ELSE ''ok'' END, ''reports idle and stale projects'', active || '' active projects, '' || idle || '' with no open issue, '' || stale || '' not updated in 14 days.'' FROM (SELECT COUNT(*) AS active, SUM(NOT EXISTS (SELECT 1 FROM issue_project_map m JOIN agent_issues a ON a.id = m.issue_id AND a.status = ''open'' WHERE m.project_code = p.project_code)) AS idle, SUM(p.updated_at < datetime(''now'',''-14 days'')) AS stale FROM projects p WHERE p.status = ''active'')"}, {"type": "sql", "name": "metrics", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = (SELECT CAST(MIN(score) AS TEXT) FROM site_ux_checks WHERE id IN (SELECT MAX(id) FROM site_ux_checks GROUP BY product)), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''site_ux_score_min'' AND EXISTS (SELECT 1 FROM site_ux_checks)"}, {"type": "sql", "name": "metrics2", "db": "AUDIT", "sql": "UPDATE metric_registry SET last_value = CAST((SELECT COUNT(DISTINCT persona_key) FROM persona_actions WHERE ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-24 hours'')) AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''staff_roles_acting_24h''"}]}', 60000, 1, 1, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'));

INSERT OR REPLACE INTO fleet_crons (name, cron_expr, task_id, enabled, timezone, updated_at)
VALUES ('staff-roster-hourly', '55 * * * *', 'staff-roster', 1, 'UTC', strftime('%Y-%m-%dT%H:%M:%SZ','now'));

