('staff_roles_acting_24h', 'operational', 'target', 'distinct personas with a persona_actions row in 24 hours', 'qnfo-audit.persona_actions (STAFF-ROSTER-1)', '>= 4', 'qnfo-fleet-control', 'agent:staff-roster', 'hourly', 'UNMEASURED', NULL, NULL);
